source("common.R")
show <- function(label, expr) { w <- NULL; r <- withCallingHandlers(tryCatch(withVisible(expr), error = function(e) paste0("ERR<", class(e)[1], "> ", conditionMessage(e))), warning = function(x) { w <<- conditionMessage(x); invokeRestart("muffleWarning") }); vis <- ""; if (is.list(r) && identical(names(r), c("value", "visible"))) { vis <- if (r$visible) "" else " (invisible)"; r <- r$value }; if (is.function(r)) r <- "FUNCTION"; cat(sprintf("%-30s %s%s%s\n", label, paste(deparse(r, control = c("digits17", "keepNA", "keepInteger", "showAttributes")), collapse = ""), vis, if (is.null(w)) "" else paste("  WARN:", w))) }
sq_src <- "void sq(int n, const double *x, double *y) { for (int i = 0; i < n; i++) y[i] = x[i] * x[i]; }"
sq <- cfunction(sq_src, out = "y", n = "n"); print(sq); print(formals(sq))
vals <- list(c(1, 2, 3), 1:3, c(TRUE, FALSE), NULL, numeric(0), integer(0), "a", list(1, 2), factor(c("a", "b")), Sys.Date(), c(a = 1, b = 2), matrix(1:4 + 0, 2), NA, NA_real_, c(NA_integer_, 2L), 2^31, 1i, as.raw(1), structure(c(1, 2), class = "foo"))
for (v in vals) show(paste("sq x=", paste(deparse(v), collapse = "")), sq(x = v))
x <- c(1, 2, 3)
for (n in list(2, 2L, 3, 4, 0, -1, NA, NA_integer_, NA_real_, 2.5, 2.0, "2", TRUE, c(1, 2), NULL, Inf, 2^31, -0, 1e-320, factor("a"), list(2))) show(paste("sq n=", deparse(n)), sq(x = x, n = n))
for (y in list(c(9, 9, 9), c(9, 9), c(9, 9, 9, 9), 1:3, c(9L, 9L, 9L, 9L), numeric(0), NULL, "a", c(a = 9, b = 9, c = 9), matrix(9, 3, 1), c(TRUE, TRUE, TRUE), NA, list(1,2,3), factor(c("a","b","c")), structure(c(9, 9, 9), class = "foo"))) show(paste("sq y=", paste(deparse(y), collapse = "")), sq(x = x, y = y))
y0 <- c(9, 9, 9); r <- sq(x = x, y = y0); cat("caller y unchanged:", identical(y0, c(9, 9, 9)), "\n")
yi <- 7:9; r <- sq(x = x, y = yi); cat("int y coerced copy:", deparse(yi), deparse(r), "\n")
show("positional", sq(3L, x)); show("positional no n", sq(, x)); show("no x", sq()); show("x missing n given", sq(n = 2))
# int outputs/inputs
ii <- cfunction("int ii(int n, const int *x, int *y, double s, int k) { int t = 0; for (int i = 0; i < n; i++) { y[i] = x[i] + k; t += x[i]; } return t + (int) s; }", out = "y", n = "n"); print(ii)
for (v in list(1:3, c(1, 2, 3), c(1.5, 2), c(NA, 1L), c(TRUE, FALSE), 2^31, c(1e10, 1), NA_real_, c(-2147483648, 1), c(a = 1L), factor("a"), numeric(0))) show(paste("ii x=", paste(deparse(v), collapse = "")), ii(x = v, s = 0, k = 1L))
for (k in list(1, 1L, 1.5, NA, NA_integer_, NA_real_, TRUE, "1", 2^31, -2^31, 2147483647, -2147483647, NULL, c(1, 2), Inf, NaN, -0, factor("a"), Sys.Date(), c(a = 1), 1e-320, 0.9999999999999999)) show(paste("ii k=", deparse(k)), ii(x = 1:2, s = 0, k = k))
for (s in list(1, 1L, TRUE, NA, NA_real_, NA_integer_, NaN, "1", NULL, c(1, 2), Inf, factor("a"), Sys.Date(), c(a = 1), 1i)) show(paste("ii s=", deparse(s)), ii(x = 1:2, s = s, k = 0L))
show("ii y dbl supplied", ii(x = 1:2, s = 0, k = 0L, y = c(5, 6)))
show("ii y dbl frac", ii(x = 1:2, s = 0, k = 0L, y = c(5.5, 6)))
show("ii y NA", ii(x = 1:2, s = 0, k = 0L, y = c(NA, 6L)))
show("ii ret INT_MIN", cfunction("int f(void) { return -2147483647 - 1; }")())
show("int ret NA in list", cfunction("int f(int n, int *y) { y[0] = -2147483647 - 1; return 1; }", out = "y", n = "n")(n = 1L))
show("dbl ret NaN", cfunction("double f(void) { return 0.0/0.0; }")())
show("void no out", cfunction("void f(double a) { }")(1))
show("void no args", cfunction("void f(void) { }")())
show("empty parens", cfunction("double f() { return 1; }")())
